class StockPortfolioTracker:
    MAX_CASH_BALANCE = float('inf')

    def __init__(self, cash_balance):
        self.portfolio = []
        self.cash_balance = cash_balance

    def _check_duplicate_stock(self, stock):
        for pf in self.portfolio:
            if pf['name'] == stock['name']:
                return pf
        return None

    def _update_or_add_stock(self, stock):
        duplicate = self._check_duplicate_stock(stock)
        if duplicate is not None:
            duplicate['quantity'] += stock['quantity']
        else:
            self.portfolio.append(stock)
        return True

    def _remove_stock_quantity(self, stock):
        for pf in self.portfolio:
            if pf['name'] == stock['name'] and pf['quantity'] >= stock['quantity']:
                pf['quantity'] -= stock['quantity']
                if pf['quantity'] == 0:
                    self.portfolio.remove(pf)
                return True
        return False

    def _calculate_cost(self, stock):
        return stock['price'] * stock['quantity']

    def _can_afford_stock(self, stock):
        return self._calculate_cost(stock) <= self.cash_balance

    def _subtract_cash(self, amount):
        self.cash_balance -= amount

    def _add_cash(self, amount):
        self.cash_balance += amount

    def _calculate_stock_value(self, stock):
        return stock['price'] * stock['quantity']

    def _build_portfolio_summary_list(self):
        summary = []
        for stock in self.portfolio:
            value = self._calculate_stock_value(stock)
            summary.append({"name": stock["name"], "value": value})
        return summary

    def add_stock(self, stock):
        return self._update_or_add_stock(stock)

    def remove_stock(self, stock):
        return self._remove_stock_quantity(stock)

    def buy_stock(self, stock):
        if not self._can_afford_stock(stock):
            return False
        self._update_or_add_stock(stock)
        self._subtract_cash(self._calculate_cost(stock))
        return True

    def sell_stock(self, stock):
        if not self._remove_stock_quantity(stock):
            return False
        self._add_cash(self._calculate_cost(stock))
        return True

    def calculate_portfolio_value(self):
        total_value = self.cash_balance
        for stock in self.portfolio:
            total_value += self._calculate_stock_value(stock)
        return total_value

    def get_portfolio_summary(self):
        summary = self._build_portfolio_summary_list()
        portfolio_value = self.calculate_portfolio_value()
        return portfolio_value, summary

    def get_stock_value(self, stock):
        return self._calculate_stock_value(stock)
